'use strict';
const I18n={
 lang:'fr',maps:{},languages:[['fr','Français'],['en','English'],['es','Español'],['de','Deutsch'],['it','Italiano'],['pt','Português'],['ru','Русский'],['uk','Українська'],['zh','中文'],['jp','日本語'],['ko','한국어'],['rc','Kréol Rénioné'],['ln','Lingala'],['ar','العربية'],['he','עברית']],
 boot(){try{const code=localStorage.getItem('xsheep-language');if(this.languages.some(([id])=>id===code))this.lang=code}catch{}},
 t(value){if(typeof value!=='string'||this.lang==='fr')return value;const dict=this.maps[this.lang]||{},part=s=>{const k=s.trim();return Object.prototype.hasOwnProperty.call(dict,k)?s.slice(0,s.length-s.trimStart().length)+dict[k]+s.slice(s.trimEnd().length):s};return value.includes('<')?value.split(/(<[^>]*>)/g).map(s=>s.startsWith('<')?s:part(s)).join(''):part(value)},
 init(){document.documentElement.lang=({jp:'ja',rc:'rcf',zh:'zh-CN'})[this.lang]||this.lang;document.documentElement.dir=['ar','he'].includes(this.lang)?'rtl':'ltr';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement.closest('script,style,#language'))continue;node.nodeValue=this.t(node.nodeValue)}for(const node of document.querySelectorAll('[aria-label],[title]'))for(const attr of ['aria-label','title']){const value=node.getAttribute(attr);if(value)node.setAttribute(attr,this.t(value))}document.title=this.t(document.title);const selector=document.getElementById('language');for(const [id,name]of this.languages){const option=document.createElement('option');option.value=id;option.textContent=name;option.lang=({jp:'ja',rc:'rcf'})[id]||id;selector.appendChild(option)}selector.value=this.lang;selector.title=this.t('Changer de langue relance la partie.');selector.addEventListener('change',()=>{try{localStorage.setItem('xsheep-language',selector.value)}catch{}location.reload()})}
};
I18n.boot();
document.addEventListener('DOMContentLoaded',()=>I18n.init(),{once:true});

